			{ quest = 7645, name = "Manna-Enriched Horse Feed", goal = true, min = 60, level = 60, side = "Alliance", races = 5, classes = 2, from = { npc = { 2357 } }, to = { npc = { 2357 } }, items = { 13724 }, rewards = { 18775 }, xp = 660, text = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills. The Argent Dawn is known as the sole purveyor of the biscuits. You also need to give her 50 gold to soothe her ruffled sensibilities." },
