			{ quest = 8053, name = "Paragons of Power: The Freethinker's Armguards", goal = true, min = 60, level = 61, classes = 2, from = { npc = { 14902 } }, to = { npc = { 14902 } }, items = { 19716 }, rewards = { 19827 }, repGain = { { 270, 150 } }, xp = 3400, text = "Bring Jin'rokh the Breaker Primal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe. Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale." },
