			{ quest = 8061, name = "Paragons of Power: The Confessor's Wraps", goal = true, min = 60, level = 60, classes = 16, from = { npc = { 14903 } }, to = { npc = { 14903 } }, items = { 19718 }, rewards = { 19843 }, repGain = { { 270, 150 } }, xp = 6600, text = "Bring Al'tabim the All-Seeing a Primal Hakkari Stanchion. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe. Al'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale." },
			{ quest = 8070, name = "Paragons of Power: The Confessor's Bindings", goal = true, min = 60, level = 60, classes = 16, from = { npc = { 14903 } }, to = { npc = { 14903 } }, items = { 19720 }, rewards = { 19842 }, repGain = { { 270, 150 } }, xp = 6600, text = "Bring Al'tabim the All-Seeing a Primal Hakkari Sash. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe. Al'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale." },
			{ quest = 8071, name = "Paragons of Power: The Confessor's Mantle", goal = true, min = 60, level = 60, classes = 16, from = { npc = { 14903 } }, to = { npc = { 14903 } }, items = { 19724 }, rewards = { 19841 }, repGain = { { 270, 150 } }, xp = 6600, text = "Bring Al'tabim the All-Seeing a Primal Hakkari Aegis. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe. Al'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale." },
			{ quest = 8304, name = "Dearest Natalia", min = 58, level = 60, from = { npc = { 15181 } }, to = { npc = { 15181 } }, kill = { 15171, 15170 }, repGain = { { 609, 100 } }, xp = 6600, text = "Commander Mar'alith at Cenarion Hold in Silithus wants you to question the inhabitants of Bronzebeard's Encampment. You will find Bronzebeard's Encampment south of Cenarion Hold. Once you have gathered the requested information, return to Commander Mar'alith." },
			{ quest = 8309, name = "Glyph Chasing", min = 58, level = 60, any = { 8304 }, from = { npc = { 15170 } }, to = { npc = { 15170 } }, items = { 20455, 20454, 20456 }, repGain = { { 609, 100 } }, xp = 8300, text = "Rutgar Glyphshaper at Bronzebeard's Encampment in Silithus wants you to venture to Hive'Ashi, Hive'Zora, and Hive'Regal and recover Glyphed Rubbings from the Glyphed Crystals of each hive. Use the Geologist's Transcription Kit to make a reasonable facsimile of the ancient glyphs. Return to Rutgar Glyphshaper when you complete this task." },
			{ quest = 8310, name = "Breaking the Code", min = 58, level = 60, any = { 8304 }, from = { npc = { 15171 } }, to = { npc = { 15171 } }, items = { 20457, 20458, 20459 }, repGain = { { 609, 100 } }, xp = 8300, text = "Frankal Stonebridge at Bronzebeard's Encampment in Silithus wants you to recover a Hive'Zora Silithid Brain, Hive'Ashi Silithid Brain, and a Hive'Regal Silithid Brain. Return to Frankal when you have completed this task." },
			{ quest = 8314, name = "Unraveling the Mystery", min = 58, level = 60, all = { 8309, 8310 }, from = { npc = { 15170 } }, to = { npc = { 15183 } }, repGain = { { 609, 75 } }, xp = 4950, text = "Rutgar Glyphshaper at Bronzebeard's Encampment wants you to deliver the Glyphed Crystal Prism to Geologist Larksbane at the Cenarion Hold in Silithus." },
			{ quest = 8315, name = "The Calling", min = 58, level = 60, any = { 8314 }, from = { npc = { 15183 } }, to = { npc = { 15183 } }, items = { 20465 }, repGain = { { 609, 200 } }, xp = 9950, text = "Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary. You have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed. Assemble an army for this task, <Name>!" },
			{ quest = 8379, name = "Armaments of War", goal = true, min = 58, level = 60, classes = 16, any = { 8315 }, from = { npc = { 15183 } }, to = { npc = { 15183 } }, rewards = { 20707, 20717 }, repGain = { { 609, 100 } }, xp = 6600 },
			{ quest = 8689, name = "Shroud of Infinite Wisdom", goal = true, min = 60, level = 60, classes = 16, from = { npc = { 15500 } }, to = { npc = { 15500 } }, items = { 20885, 20870, 20859, 20863 }, rewards = { 21412 }, repGain = { { 609, 100 } }, xp = 6600, text = "Bring 1 Qiraji Martial Drape, 2 Jasper Idols, 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest." },
			{ quest = 8697, name = "Ring of Infinite Wisdom", goal = true, min = 60, level = 60, classes = 16, from = { npc = { 15498 } }, to = { npc = { 15498 } }, items = { 20888, 20871, 20860, 20864 }, rewards = { 21411 }, repGain = { { 609, 100 } }, xp = 6600, text = "Bring 1 Qiraji Ceremonial Ring, 2 Obsidian Idols, 5 Silver Scarabs and 5 Bone Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest." },
			{ quest = 8705, name = "Gavel of Infinite Wisdom", goal = true, min = 60, level = 60, classes = 16, from = { npc = { 15499 } }, to = { npc = { 15499 } }, items = { 20890, 20868, 20861, 20865 }, rewards = { 21410 }, repGain = { { 609, 100 } }, xp = 6600, text = "Bring 1 Qiraji Ornate Hilt, 2 Lambent Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest." },
